mapper.select:
WITH AA20 AS( /*소속기관별상담사*/ SELECT USER_ID AS USER_ID , C##RG.DEC_B64(FLNM_ENCPT) AS FLNM , OGDP_DEPT_CD AS DEPT_CD FROM SAA200 /* 사용자 */ , SCA100 /* 종사자 */ WHERE 1=1 AND SCA100.ENFSN_NO = SAA200.ENFSN_NO AND SCA100.UNT_TASKWK_SE_CD = 'U11' --청소년사이버상담 AND SCA100.ENFSN_ROLE_SE_CD = '3' --종사자 AND SCA100.DEL_YN = 'N' AND SAA200.JOIN_APRV_YN = 'Y'
AND SCA100.OGDP_DEPT_CD = #{deptCd}
) ,DD20 AS( SELECT AA20.USER_ID AS USER_ID , NVL(SUM(CASE WHEN AYB200.CHTT_TYPE_SE_CD IN ('08','02','07','05','06') THEN 1 ELSE 0 END), 0) AS CHTT /*채팅*/ , NVL(SUM(CASE WHEN AYE120.BBSCTT_TYPE_SE_CD = '05' THEN 1 ELSE 0 END), 0) AS SEC /*나의 게시판상담실적:비밀*/ , NVL(SUM(CASE WHEN AYE120.BBSCTT_TYPE_SE_CD = '01' THEN 1 ELSE 0 END), 0) AS SOLBOARD /*나의 게시판상담실적:솔로봇*/ , NVL(SUM(CASE WHEN AYE100.BBSCTT_TYPE_SE_CD IN ('31','18') THEN 1 ELSE 0 END), 0) AS ETC1 /*나의 게시판상담실적:기타상담_네이버,오픈채팅*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '36' THEN 1 ELSE 0 END), 0) AS ETC2 /*나의 게시판상담실적:기타상담_구글*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '08' THEN 1 ELSE 0 END), 0) AS BORDCOUN /*나의 댓글상담실적:댓글*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '02' THEN 1 ELSE 0 END), 0) AS SOLREPLE /*나의 댓글상담실적:솔로봇*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '04' THEN 1 ELSE 0 END), 0) AS WEB /*나의 댓글상담실적:웹심리*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '03' THEN 1 ELSE 0 END), 0) AS EUM /*나의 댓글상담실적:이음e*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '15' THEN 1 ELSE 0 END), 0) AS PARENT /*나의 댓글상담실적:자녀맘*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '14' THEN 1 ELSE 0 END), 0) AS GOMIN /*나의 댓글상담실적:고민해결백과*/ , NVL(SUM(CASE WHEN AYE100.BBSCTT_TYPE_SE_CD = '35' THEN 1 ELSE 0 END), 0) AS OUTRC /*아웃리치*/ , NVL(SUM(CASE WHEN AYE110.BBSCTT_TYPE_SE_CD = '12' THEN 1 ELSE 0 END), 0) AS CYBER /*사이버상담후기*/ , NVL(SUM(CASE WHEN AYA120.BBSCTT_TYPE_SE_CD IN ('24','05','35','18','02','31') THEN 1 ELSE 0 END), 0) AS DSCSN /*연계상담*/ , NVL(SUM(CASE WHEN AYA190.BBSCTT_TYPE_SE_CD IN ('24','05','35','18','02','31') THEN 1 ELSE 0 END), 0) AS AFTFCT /*사후관리*/ , COUNT(SEB400.SRVC_PVSN_RQST_NO) AS LINK /*연계의뢰*/ FROM AA20 LEFT OUTER JOIN AYE100 /*사이버상담게시글*/ ON AA20.USER_ID = AYE100.FRST_RGTR_ID AND AYE100.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 AND AYE100.BBSCTT_TYPE_SE_CD IN ('31','18','35') LEFT OUTER JOIN AYE110 /*사이버상담댓글 */ ON AA20.USER_ID = AYE110.FRST_RGTR_ID AND AYE110.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 AND AYE110.BBSCTT_TYPE_SE_CD IN ('36','08','02','12') LEFT OUTER JOIN AYE120 /*사이버상담답글 */ ON AA20.USER_ID = AYE120.FRST_RGTR_ID AND AYE120.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 AND AYE120.BBSCTT_TYPE_SE_CD IN ('05','01') LEFT OUTER JOIN AYB200 /*채팅이력 */ ON AA20.USER_ID = AYB200.FRST_RGTR_ID AND AYB200.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 AND AYB200.CHTT_TYPE_SE_CD IN ('08','02','07','05','06') LEFT OUTER JOIN AYA120 /*위기상담_개인 */ ON AA20.USER_ID = AYA120.FRST_RGTR_ID AND AYA120.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 AND AYA120.BBSCTT_TYPE_SE_CD IN ('24','05','35','18','02','31') LEFT OUTER JOIN AYA190 /*사후관리 */ ON AA20.USER_ID = AYA190.FRST_RGTR_ID AND AYA190.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 AND AYA190.BBSCTT_TYPE_SE_CD IN ('24','05','35','18','02','31') LEFT OUTER JOIN SEB400 /*서비스제공의뢰 */ ON AA20.USER_ID = SEB400.FRST_RGTR_ID AND SEB400.FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 GROUP BY USER_ID ) SELECT AA20.FLNM AS MEM_NAME /*상담사*/ , NVL(CHTT,0) AS CHTT /*채팅 */ , NVL(AYC170.NTABRD_ASGN_NOCS,0) AS BG_01 /*게시판상담할당량 */ , SEC AS SEC /*나의 게시판상담실적:비밀*/ , SOLBOARD AS SOLBOARD /*나의 게시판상담실적:솔로봇*/ , ETC1+ETC2 AS ETC /*나의 게시판상담실적:기타상담*/ , SEC + SOLBOARD + ETC1 + ETC2 AS BORD_TOT_CNT /*나의 게시판상담실적 합*/ , NVL(AYC170.CMNT_ASGN_NOCS,0) AS CMNT_ASGN_NOCS /*댓글상담할당량 */ , BORDCOUN AS BORDCOUN /*나의 댓글상담실적:댓글*/ , SOLREPLE AS SOLREPLE /*솔로봇*/ , WEB AS WEB /*웹심리*/ , EUM AS EUM /*이음e*/ , PARENT AS PARENT /*자녀맘*/ , GOMIN AS GOMIN /*고민해결백과*/ , BORDCOUN + SOLREPLE + WEB + EUM + PARENT + GOMIN AS REP_TOT_CNT /*나의댓글상담실적 합*/ , OUTRC AS OUTRC /*아웃리치*/ , CYBER AS CYBER /*사이버상담후기*/ , DSCSN AS DSCSN /*연계상담*/ , AFTFCT AS AFTFCT /*사후관리*/ , LINK AS LINK /*연계의뢰*/ FROM AYC170 /*월별상담자게시판댓글할당*/ , AA20 LEFT OUTER JOIN DD20 ON AA20.USER_ID = DD20.USER_ID LEFT OUTER JOIN AYB200 /*채팅이력*/ ON AA20.USER_ID = AYB200.CNSLTNT_ID AND AYB200.CHTT_BGNG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 WHERE AYC170.RLVT_YM = SUBSTR(#{startDate},1,6) /*FROMYM*/ AND AYC170.DEL_YN = 'N' AND AA20.USER_ID = #{sUserId} AND AYC170.TASKWK_TYPE_DEPT_CD = AA20.DEPT_CD GROUP BY AA20.FLNM , CHTT , NVL(AYC170.NTABRD_ASGN_NOCS,0) , SEC , SOLBOARD , ETC1+ETC2 , SEC + SOLBOARD + ETC1 + ETC2 , NVL(AYC170.CMNT_ASGN_NOCS,0) , BORDCOUN , SOLREPLE , WEB , EUM , PARENT , GOMIN , BORDCOUN + SOLREPLE + WEB + EUM + PARENT + GOMIN , OUTRC , CYBER , DSCSN , AFTFCT , LINK
